/* ── Применение: замена meta description и проверка ────────────────────────── */
$changed = []; $same = []; $fail = []; $outOfRange = [];
foreach ($map as $rel => $desc) {
    $path = $root . '/' . $rel;
    if (!is_file($path)) { $fail[] = $rel . ' — нет файла'; continue; }
    $t = (string)file_get_contents($path);

    $len = mb_strlen($desc);
    if ($len < 140 || $len > 160) { $outOfRange[] = $rel . ' — ' . $len . ' знаков'; }

    if (!preg_match('#<meta name="description" content=".*?" />#s', $t)) { $fail[] = $rel . ' — нет тега description'; continue; }
    $new = (string)preg_replace('#<meta name="description" content=".*?" />#s', '<meta name="description" content="' . $desc . '" />', $t, 1);
    if ($new === $t) { $same[] = $rel; continue; }
    if (substr_count($new, $desc) !== 1) { $fail[] = $rel . ' — после замены описание не одно'; continue; }
    if (!$dry) {
        $bak = $backDir . '/' . $stamp . '__' . str_replace('/', '__', $rel) . '.bak';
        if (!is_file($bak)) { copy($path, $bak); }
        file_put_contents($path, $new);
    }
    $changed[] = $rel;
}

