             'sweb-migration', 'node_modules', 'Досрочное погашение', 'Инженерные'];
$rows = ['ИТОГОВЫЕ meta description (снято ' . date('d.m.Y H:i') . ')', '',
         str_pad('СТРАНИЦА', 48) . ' | ДЛИНА | ОПИСАНИЕ'];
$total = 0; $inRange = 0; $short = 0; $long = 0;
$it = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root, FilesystemIterator::SKIP_DOTS));
$files = [];
foreach ($it as $f) {
    if (!$f->isFile() || strtolower($f->getExtension()) !== 'html') { continue; }
    $rel = str_replace('\\', '/', substr($f->getPathname(), strlen($root) + 1));
    $bad = false;
    foreach (explode('/', $rel) as $p) { if (in_array($p, $skipDirs, true)) { $bad = true; } }
    if ($bad || preg_match('/^yandex_[0-9a-f]+\.html$/i', basename($rel))) { continue; }
    $files[] = $rel;
}
sort($files);
foreach ($files as $rel) {
    $h = (string)file_get_contents($root . '/' . $rel);
    $m = preg_match('#<meta name="description" content="(.*?)" />#s', $h, $mm) ? $mm[1] : '';
    $l = mb_strlen($m);
    $total++;
    if ($l >= 140 && $l <= 160) { $inRange++; } elseif ($l < 140) { $short++; } else { $long++; }
    $rows[] = str_pad($rel, 48) . ' | ' . str_pad((string)$l, 5) . ' | ' . $m;
}
$rows[] = '';
$rows[] = 'страниц: ' . $total . ', в норме 140–160: ' . $inRange . ', короче: ' . $short . ', длиннее: ' . $long;
if (!$dry) { file_put_contents($root . '/shots/_seo-descriptions-after.txt', implode("\n", $rows) . "\n"); }

echo ($dry ? "(пробный прогон)\n" : '') . 'Изменено страниц: ' . count($changed) . ', уже были нужные: ' . count($same) . "\n";
if ($outOfRange) { echo "Вне нормы 140–160:\n"; foreach ($outOfRange as $x) { echo '  ! ' . $x . "\n"; } }
if ($fail) { echo "ОШИБКИ:\n"; foreach ($fail as $x) { echo '  ! ' . $x . "\n"; } }
echo 'По всему сайту: страниц ' . $total . ', в норме ' . $inRange . ', короче ' . $short . ', длиннее ' . $long . "\n";
echo 'Отчёт: shots/_seo-descriptions-after.txt' . "\n";
exit($fail ? 1 : 0);




